// newsnowSourceFieldKind identifies which typed slot of newsnowMetadataSource
// a JSON key maps to. It exists so the ordered marshaller can stay strongly
// typed instead of falling back to an untyped map.
type newsnowSourceFieldKind int

const (
	newsnowFieldRedirect newsnowSourceFieldKind = iota
	newsnowFieldName
	newsnowFieldType
	newsnowFieldDisable
	newsnowFieldDesc
	newsnowFieldColumn
	newsnowFieldHome
	newsnowFieldRuntimeSecrets
	newsnowFieldColor
	newsnowFieldInterval
	newsnowFieldTitle
)

// newsnowSourceKey is one ordered JSON key of a source entry.
type newsnowSourceKey struct {
	Name string
	Kind newsnowSourceFieldKind
}

// newsnowRuntimeSecrets mirrors SourceRuntimeSecretsConfig.
type newsnowRuntimeSecrets struct {
	Description       string   `json:"description"`
	RequiredAnyOfKeys []string `json:"requiredAnyOfKeys,omitempty"`
	SuggestedKeys     []string `json:"suggestedKeys,omitempty"`
	EnvFallbackKeys   []string `json:"envFallbackKeys,omitempty"`
}

// newsnowMetadataSource is one entry of the metadata endpoint's source
// registry. Fields are pointers (or omitempty) so that absent optional keys
// are omitted exactly like the NestJS JSON serialization.
type newsnowMetadataSource struct {
	Keys           []newsnowSourceKey
	Name           string
	Type           string
	Disable        string
	Desc           string
	Column         string
	Home           string
	RuntimeSecrets *newsnowRuntimeSecrets
	Color          string
	Interval       int
	Title          string
	Redirect       string
}

// newsnowRegistryEntry pairs a source id with its ordered metadata entry.
type newsnowRegistryEntry struct {
	ID     string
	Source newsnowMetadataSource
}

