// domesticSourceIDs is DOMESTIC_SOURCE_IDS: the china column's source ids,
// which the domestic opinion index uses to decide whether a report is
// domestic.
var domesticSourceIDs = func() map[string]struct{} {
	out := make(map[string]struct{}, 32)
	for _, column := range newsnowColumnRegistry {
		if column.ID != domesticColumnID {
			continue
		}
		for _, id := range column.Sources {
			out[id] = struct{}{}
		}
	}
	return out
}()

// domesticColumnID names the metadata column whose sources count as domestic.
const domesticColumnID = "china"
